sql.where:
t.deleted = 0

    AND t.version_id = #{req.versionId}


    AND t.res_id = #{req.resId}


    AND t.res_code LIKE CONCAT('%', #{req.resCode}, '%')


    AND t.res_name LIKE CONCAT('%', #{req.resName}, '%')


    AND t.overload_minutes > 0


    AND t.work_date BETWEEN #{req.workDate[0]} AND #{req.workDate[1]}


    AND t.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
